package tw.com.tft.documentscanner.view;import android.content.*;import android.graphics.*;import android.graphics.drawable.Drawable;import android.util.*;import android.view.*;import androidx.annotation.Nullable;import androidx.appcompat.widget.AppCompatImageView;public class ZoomableImageView extends AppCompatImageView{private final Matrix m=new Matrix();private ScaleGestureDetector s;private GestureDetector g;private float min=1,cur=1,lx,ly;private boolean drag;public ZoomableImageView(Context c){super(c);init(c);}public ZoomableImageView(Context c,@Nullable AttributeSet a){super(c,a);init(c);}private void init(Context c){setScaleType(ScaleType.MATRIX);s=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){float t=Math.max(min,Math.min(min*5,cur*d.getScaleFactor()));float f=t/cur;m.postScale(f,f,d.getFocusX(),d.getFocusY());cur=t;setImageMatrix(m);return true;}});g=new GestureDetector(c,new GestureDetector.SimpleOnGestureListener(){public boolean onDoubleTap(MotionEvent e){resetZoom();return true;}});}public void setImageBitmap(Bitmap b){super.setImageBitmap(b);post(this::resetZoom);}public void resetZoom(){Drawable d=getDrawable();if(d==null||getWidth()==0)return;float sc=Math.min(getWidth()/(float)d.getIntrinsicWidth(),getHeight()/(float)d.getIntrinsicHeight());min=cur=sc;m.reset();m.postScale(sc,sc);m.postTranslate((getWidth()-d.getIntrinsicWidth()*sc)/2f,(getHeight()-d.getIntrinsicHeight()*sc)/2f);setImageMatrix(m);}public boolean onTouchEvent(MotionEvent e){g.onTouchEvent(e);s.onTouchEvent(e);switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:lx=e.getX();ly=e.getY();drag=true;return true;case MotionEvent.ACTION_MOVE:if(drag&&!s.isInProgress()){m.postTranslate(e.getX()-lx,e.getY()-ly);lx=e.getX();ly=e.getY();setImageMatrix(m);}return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:drag=false;return true;}return true;}}